{
  "technical_and_design_decisions": [
    "All new features will be built on top of existing Spring XD 1.3.x core stream lifecycle, module management, and message bus abstraction layers to avoid reimplementing existing functionality.",
    "Message bus resource cleanup will use the native admin client APIs of supported message bus implementations (RabbitMQ, Kafka) to ensure reliable and performant resource deletion.",
    "Stream edit functionality will only support modification of deployment properties and module configurations in this increment, not changes to core stream topology (adding/removing modules) to limit scope and reduce risk.",
    "Deployment manifest file loading will support standard Spring Boot-compatible YAML and .properties file formats to align with existing Spring configuration conventions.",
    "Trace functionality will leverage Spring Integration's built-in global wiretap feature as specified in the provided documentation, rather than implementing custom logging/notification logic.",
    "Side channels will be registered as additional bindable channels on the message bus during stream deployment, with unique naming conventions tied to the stream and module name to avoid conflicts.",
    "The NYC taxi trip reference architecture will use existing Spring XD out-of-the-box modules (e.g., HTTP source, transform processor, JDBC sink) where possible to minimize custom code development.",
    "All new features will be exposed via the existing Spring XD shell CLI and REST API with no changes to existing client interfaces to maintain backward compatibility."
  ],
  "assumptions": [
    "The target deployment environment for this increment is Spring XD 1.3.x, the latest stable release prior to its replacement by Spring Cloud Data Flow.",
    "The message bus in use is either RabbitMQ 3.6+ or Kafka 0.10+, both of which have stable, well-documented admin client APIs for resource management.",
    "The DEBS 2015 NYC taxi trip dataset schema and sample data are publicly available via the challenge's published resources with no access restrictions.",
    "Existing Spring XD unit and integration test infrastructure is available for reuse, eliminating the need to build new test harnesses from scratch.",
    "All new features will be tested against both RabbitMQ and Kafka message bus implementations to ensure cross-implementation compatibility.",
    "The stream edit functionality will not support modifying the core stream definition (e.g., adding/removing modules, changing stream topology) in this increment, as that is out of scope for the current user stories."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Stream Destruction Resource Cleanup Implementation",
      "activity_description": "Develop logic to identify and delete all message bus queues/topics associated with a stream when the stream is destroyed, using existing message bus admin client APIs and hooking into the Spring XD stream lifecycle.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Stale Message Bus Resource Cleanup Utility",
      "activity_description": "Build a CLI command and background job to scan for and delete orphaned queues/topics that are no longer linked to any active Spring XD stream, with logging for all cleanup actions.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "Stream Edit Functionality Implementation",
      "activity_description": "Add a REST API endpoint and shell CLI command to update deployment properties and module configurations for deployed or undeployed streams without requiring full stream destruction and recreation, including input validation and error handling.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A4",
      "activity_name": "Deployment Manifest File Loading Support",
      "activity_description": "Extend the stream deployment CLI to accept a path to a local YAML or properties file containing deployment properties, with support for merging file-based properties with inline properties provided via the command line.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5",
      "activity_name": "Reference Architecture Framework Setup",
      "activity_description": "Create the base structure, documentation template, and guidelines for Spring XD reference architectures, including a catalog of common enterprise use case patterns for field engineer reuse.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "Trace Property Support for Streams",
      "activity_description": "Implement support for module.*.trace and module.<specific-module>.trace deployment properties, leveraging Spring Integration's global wiretap feature to enable trace logging/notifications for targeted modules in a stream, including wildcard matching.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Side Channel Implementation for Modules",
      "activity_description": "Add support for defining optional non-primary input/output side channels per module during stream deployment, registered with the message bus with unique naming conventions, and configurable via deployment properties for use cases like tapping or progress tracking.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8",
      "activity_name": "NYC Taxi Trip Analytics Reference Architecture Implementation",
      "activity_description": "Build the specific reference architecture for the DEBS 2015 NYC taxi trip real-time analytics challenge, including sample stream definitions, custom processing modules for trip data, and end-to-end testing with the sample dataset.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 23
  }
}

